# -*- coding: utf-8 -*-
"""v41 第二批：21个旅行路线 v37 占位节点重写"""

R = [
("travel_north_day2","北方路线·第二天","第二天清晨，商队的铃铛把你叫醒。帐篷外的火堆还冒着青烟，霜冻的地面在脚下咯吱作响。","队伍里的老马夫递给你一碗热粥：「喝吧。今天要翻两道丘陵，路不好走。」你接过碗，粥的热气扑在脸上。远处，官道像一条灰带子，伸向灰蒙蒙的天际。","午间，你们路过一片烧焦的村庄。没有人说话。商队的护卫握紧了缰绳，老马夫叹了口气：「去年冬天的事。北边不太平，仗打了好几年了。」","傍晚扎营时，你把随身带的干粮分了一半给路边一个逃难的孩子。他接过干粮，眼睛亮了一下，又警惕地缩回树后。你看着他，想起铁门关的那些日子。",[("继续赶路","travel_resolve"),("打听北方的局势","travel_north_explore")]),
("travel_north_day2_solo","北方路线·独行·第二天","独行的第二天，北方的风已经吹得你脸颊生疼。你裹紧袍子，沿着官道一步一步往前。","正午，你在一棵枯树下歇脚。远处有军队调动的旗帜，一队骑兵从你身边驰过，扬起一阵尘土。你压低帽檐，等他们过去才继续走。","黄昏，你找到一间废弃的猎屋过夜。屋里积着灰，但屋顶还算完整。你生起火，烤着硬邦邦的干粮。火光把你的影子投在墙上，一晃一晃的。","夜里，风大了。你听见远处传来狼嚎，一声接一声。你往火堆里添了柴，把刀放在手边。这一夜，你没有睡得很沉。",[("天亮继续赶路","travel_resolve"),("在猎屋周围看看","travel_north_explore")]),
("travel_north_explore","北方路线·探索","你离开官道，去看了看路旁的遗迹——一座倒塌的瞭望塔。","塔身歪斜，长满了青苔。你攀上去，发现塔内还留着旧的烽火台——那是不打仗的年月，用来传递消息的。你伸手摸了摸石壁，指尖触到一些刻痕。","那是一些名字。密密麻麻的，刻满了半面墙。每个名字下面，都刻着一个日期。你数了数，最早的，是三十年前。","你忽然明白这些名字是什么了——守卫这座塔的士兵。一代又一代，把名字留在这里，像一种沉默的誓言。你在最下面，也刻下了自己的名字。然后你转身，回到官道。",[("继续赶路","travel_resolve"),("回到商队","travel_north_day2")]),
("travel_south_day2","南方路线·第二天","南方的路，第二天就换了颜色。北方的灰黄被抛在身后，路边的树开始变得高大茂密，空气里也多了潮湿的气息。","商队的骡子走得慢，你有大把的时间看风景。路旁有农人在田里劳作，有孩子在溪边捉鱼——和北方完全不同，这里的日子，像是用另一种节奏过的。","午间，你们在一个小镇歇脚。镇子不大，但热闹：卖糖人的、卖布匹的、耍把式的，挤挤挨挨。你用一枚铜板买了根糖葫芦，酸甜的滋味在嘴里化开。","你忽然觉得，这一路向南，像是走进了另一个世界。北方的雪、铁与战争，被远远地留在了身后。",[("继续赶路","travel_resolve"),("在小镇多待一会儿","travel_south_explore")]),
("travel_south_day2_solo","南方路线·独行·第二天","独行的第二天，你走进了一片茂密的树林。阳光透过树叶，在地上洒下碎金。","这条路比官道近，但难走。树根盘错，藤蔓横生。你拨开枝叶前行，忽然听见前方有流水声——一条小溪横在面前。","你蹲下来，掬了一捧水洗脸。水很凉，带着草木的清香。你直起腰，忽然看见溪对岸的树丛动了一下。你屏住呼吸——一只鹿，正低头饮水。","你站在原地，看着那只鹿。它抬起头，看了你一会儿，然后迈开步子，消失在林深处。你笑了笑，跳过小溪，继续赶路。",[("继续赶路","travel_resolve"),("沿着鹿的足迹看看","travel_south_explore")]),
("travel_south_explore","南方路线·探索","你在路边发现一座废弃的神庙。石阶上长满了青苔，但庙门还完整。","你推开庙门，灰尘扑簌簌落下来。庙里供着一尊神像——不是大陆常见的任何一位神。神像的手里，托着一枚贝壳。","你在神像前的供桌上，发现一本泛黄的册子。翻开，里面记录着这座庙的历史：这里供奉的是「海之母」，曾经是沿海渔民出海前必拜的神。","「如今，渔民们都去拜新神了。」册子最后一行写着，「但海之母，还在等着她的孩子们回来。」你合上册子，对着神像鞠了一躬，把册子放回原处。",[("继续赶路","travel_resolve"),("回到商队","travel_south_day2")]),
("travel_east_day2","东方路线·第二天","东方的路，第二天开始变得平坦。平原在眼前铺开，麦田一片连着一片，远处的村庄升起炊烟。","你跟着商队走，路边的景色一成不变，又一直在变。你渐渐明白，东方是另一种富饶——不是北方的铁，不是南方的盐，是脚下的土地本身。","午间，你们在一座驿站歇脚。驿站里贴着官府的告示：东边某个县，闹了「怪病」，来往行人绕行。你多看了那告示几眼，把路线记在心里。","黄昏扎营时，你在营火边听商队的老人讲东边的传说：承天山下，埋着一道会发光的裂缝，谁靠近它，谁就会忘记时间。你没有接话，但心里咯噔了一下。",[("继续赶路","travel_resolve"),("打听怪病的传闻","travel_east_explore")]),
("travel_east_day2_solo","东方路线·独行·第二天","独行的第二天，你在平原上走得很快。没有商队拖累，你的步子轻快得多。","正午，你在一棵大槐树下歇脚。树下有块磨得发亮的石头——看来是路人们惯常歇脚的地方。你掏出干粮，就着凉水啃。","忽然，一个赶路的老者在你旁边坐下，也掏出干粮啃了起来。他打量了你几眼：「小兄弟，一个人走东边？」「嗯。」「胆子不小。」他说，「东边地界大，人也杂。一个人走，小心些。」","你谢过他的提醒。他摆摆手，啃完干粮，拍拍屁股走了。你看着他远去的背影，又看看自己面前的路，把行囊紧了紧。",[("继续赶路","travel_resolve"),("追上去问路况","travel_east_explore")]),
("travel_east_explore","东方路线·探索","你离开官道，去看传说中那道「会发光的裂缝」。你找到它时，天色将晚。","它不在山脚，在一座矮丘的背面。一道裂缝，从地面裂开，不宽，但深不见底。裂缝边缘的石壁上，覆着一层淡蓝色的光，像霜，又像雾。","你蹲在裂缝边，盯着那层光看了很久。你伸手想碰——手指刚靠近，一阵恍惚袭来，你觉得时间好像慢了半拍。你猛地缩回手，心跳如鼓。","你后退几步，稳住心神。你想起那些传说，想起承天山。你决定把这个发现记在心里，然后快步离开——有些东西，不是现在的你该碰的。",[("回到官道","travel_resolve"),("记住这个位置","travel_east_day2")]),
("travel_elf_day2","精灵路线·第二天","通往银叶城的路，第二天就钻进了森林。树木越来越高，阳光越来越少，空气里弥漫着苔藓和树脂的气息。","商队向导说，这条路是精灵们开辟的「静路」——路上的每一棵树，都是精灵种下的。你抬头，树枝在头顶交织成穹顶，偶尔有银色的光点从树缝漏下来。","午间，你们在一处林间空地歇脚。空地上立着一块石碑，碑文是精灵文。向导说：「这是三百年前，一位精灵长老的墓。他在人类战争中救了一整队士兵。」","你站在碑前，读了很久那看不懂的碑文。你想起精灵们常说的一句话：时间长河里的每一个善举，都会在某个时刻，开出花来。",[("继续赶路","travel_resolve"),("在森林里探索","travel_elf_explore")]),
("travel_elf_day2_solo","精灵路线·独行·第二天","独行进入森林的第二天，你迷路了。","不是那种彻底的迷失——你大概知道方向，但精灵的森林有自己的意志。你沿着直觉走了半日，发现又绕回了同一棵双生树前。","你索性坐下来，靠着树干休息。你注意到，这棵树的树皮上，刻着一行小小的字——是人类文字：「第三十七次经过这里。精灵树，你真倔。」你笑了。","你在树下歇够了，重新辨别方向。这一次，你选择跟着一只飞过的银色小鸟走。它带着你，七拐八绕，居然真的把你带出了林子，眼前豁然开朗——银叶城的树冠，正在远处闪光。",[("走向银叶城","travel_resolve"),("回头看看森林","travel_elf_explore")]),
("travel_elf_explore","精灵路线·探索","你在森林深处发现了一棵与众不同的树——它的树皮泛着淡淡的银光，像被月光浸过。","你走近它。树下落着几片银色的叶子，你捡起一片，入手冰凉，边缘锋利得像薄刃。你把它收进怀里。","你绕着树走了半圈，发现树根处有一个小小的树洞。洞里放着一只陶罐，罐口用蜡封着。你犹豫了一下，没有打开——那不是你的东西。","你只在树洞边放了一枚铜板，当作「路过的礼物」。精灵们说，森林会记住每一次善意的触碰。你离开时，回头看了一眼，那棵银树在暮色里，静静地发着光。",[("继续赶路","travel_resolve"),("回到商队","travel_elf_day2")]),
("travel_dwarf_day2","矮人路线·第二天","通往铁峰堡的路，第二天开始爬坡。官道变成了山道，商队的骡子喘着粗气，一步一步往上挪。","风变冷了，夹着矿石和硫磺的气味。向导说，闻到这味儿，说明离矮人的地界不远了。山体开始裸露，露出深色的岩层，像巨兽的骨骼。","午间，你们在一处山隘歇脚。隘口有一座石亭，亭柱上刻着矮人文。向导念道：「过客须知：山里有客人，也有强盗；锤子可以借，手艺不能丢。」你听着，觉得矮人真是有趣的种族。","傍晚，你们终于看见了铁峰堡的影子——一座嵌在山腹里的城，烟囱冒着黑烟，把半边天都熏成了灰色。",[("进城","travel_resolve"),("在山隘看看","travel_dwarf_explore")]),
("travel_dwarf_day2_solo","矮人路线·独行·第二天","独行翻山的第二天，你在一个岔路口犯了难。","两条路：一条大路，绕远，但平坦；一条小路，近，但要穿过一段废弃的矿道。一个赶驴的矮人告诉你：「小路近，但矿道里黑。你要是怕黑，走大路。」","你选了小路。你点起火把，走进矿道。矿道里很安静，只有你的脚步声和滴水声。墙上还有旧的挖痕，和一些看不懂的刻字。","你走到一半，火把的光忽然跳了一下。你停下脚步，屏住呼吸——前方的黑暗里，有什么东西，正静静地看着你。你握紧了火把，又往前走了一步。",[("继续前进","travel_resolve"),("退回大路","travel_dwarf_day2")]),
("travel_dwarf_explore","矮人路线·探索","你在山道旁发现一处废弃的矿口。木支架已经腐朽，矿口黑洞洞的，像一只睁着的眼睛。","你犹豫了一下，还是钻了进去。里面比想象中深。走了几十步，你发现墙上刻着一些图画——不是文字，是画：一群人，围着一团火，火里有一颗跳动的心。","你在画前站了很久。那团火、那颗心——你忽然想起，矮人族流传的那句话：铁峰堡的熔炉里，跳动着大地的心脏。","你没有再深入。你退出矿口，把洞口用碎石掩好——你不想让别的人，也看见这些画。有些秘密，知道的人越少越好。",[("回到山道","travel_resolve"),("继续赶路","travel_dwarf_day2")]),
("travel_west_day2","西方路线·第二天","西边的路，第二天就换了天地。平原被抛在身后，群山像巨墙一样横在眼前。","商队在一条河谷里扎营歇脚。河水清澈见底，你蹲在河边洗了把脸，水凉得扎手——是雪山融水。","午间，你们遇到一队下山的矮人商贩。他们背着大包小包，满载着矿石和铁器。两队人交换了消息，矮人商贩听说你们要去铁峰堡，咧嘴笑了：「那地方，好酒，好锤子，好客人。」","黄昏，你坐在营火边，看着西边的山影一点点沉入暮色。你忽然觉得，这一路走下来，你遇见的每一个人，都在用自己的方式活着。",[("继续赶路","travel_resolve"),("在河谷探索","travel_west_explore")]),
("travel_west_day2_solo","西方路线·独行·第二天","独行西进的第二天，你在河谷里遇上一场暴雨。","雨来得又快又急，你无处可躲，只能缩在一棵老树下，用袍子蒙住头。雨水顺着树干流下来，把地面冲出一条条小沟。","雨下了半个时辰才停。你抖落袍子上的水，继续赶路。河谷被洗得干干净净，空气里全是泥土和草叶的气息。","你踩着湿漉漉的石头过河，忽然发现河底有个东西在闪光。你蹲下去，捞起来一看——是一枚被水冲亮的铜币，已经锈得看不出年号。你把它揣进怀里，继续上路。",[("继续赶路","travel_resolve"),("在河谷里再找找","travel_west_explore")]),
("travel_west_explore","西方路线·探索","你在河谷边发现一处塌陷的山洞。洞口堆着碎石，但缝隙里透出微弱的光。","你搬开几块石头，钻了进去。洞里不大，但四壁都刻着画——和你在矮人矿道里看到的很像：火焰、锤子、一颗跳动的心。","不同的是，这里的壁画更古老。画的边缘已经模糊，你凑近了才看清：那团火焰旁边，还画着一个人影。人影的手，正伸向火焰。","你在洞里待了很久。你猜不出这壁画想说什么——是警告，还是指引？你退出山洞，把碎石重新堆好。有些问题，也许要等到铁峰堡，才有答案。",[("回到河谷","travel_resolve"),("继续赶路","travel_west_day2")]),
("travel_desert_day2","沙漠路线·第二天","沙漠的第二天，你才真正见识了它的脾气。","清晨还凉飕飕的，到了正午，太阳像烙铁一样烤着地面。空气在颤抖，远处的沙丘像在流动。你裹着防沙的布巾，一步一步地挪。","午间，商队在一处岩壁下歇脚。岩壁投下窄窄的影子，所有人和牲口都挤在那片影子里，像一群快被晒干的鱼。","黄昏，太阳终于斜下去。风开始变凉，你裹紧袍子。商队向导说：「沙漠里，最要命的不是热，是温差。白天晒掉皮，晚上冻掉牙。」你听着，把干粮又省下了一口。",[("继续赶路","travel_resolve"),("在岩壁附近看看","travel_desert_explore")]),
("travel_desert_day2_solo","沙漠路线·独行·第二天","独行穿越沙漠的第二天，你尝到了绝望的滋味。","水快喝完了。你的嘴唇干裂，喉咙像着火一样。太阳毒辣辣地挂着，连风都是烫的。你开始怀疑，自己是不是选错了路。","你靠着最后一点意志，机械地迈着步子。忽然，你脚下踢到一个硬物——你低头，刨开沙子，是一只水囊。沉甸甸的，灌满了水。","你愣了一会儿，拧开盖子，先抿了一小口，然后把水囊紧紧抱在怀里。沙漠里有人放水囊——这是给迷路的人留的活路。你记住了这个位置，心想：将来，我也要放一只。",[("继续赶路","travel_resolve"),("在附近找找标记","travel_desert_explore")]),
("travel_desert_explore","沙漠路线·探索","你在一处沙丘的背风面，发现了一具骸骨。","它半埋在沙里，身上还裹着破旧的袍子。你蹲下来，小心地翻看——骸骨旁边，散落着一卷羊皮纸。","你捡起羊皮纸，拂去沙子。上面用褪色的墨水写着：「第二十七日，断水。往东走，有一座绿洲——但我走不动了。如果后人看到这个，把我的水囊带走，往东。」","你按照羊皮纸的指引，向东走了半日，果然找到了一口枯井——井里没有水，但井壁上，有人刻着一个箭头，指向更深处的沙漠。你站在井边，望着箭头所指的方向，久久没有说话。",[("沿箭头方向走","travel_resolve"),("把骸骨埋了再走","travel_desert_day2")]),
]

def build(nid, place, text, opts):
    return '''N["%s"]=function(){return{
place:"%s",
text:[
%s
],
options:[
%s
]
}};''' % (nid, place,
   ",\n".join('"%s"' % t.replace('"','「') for t in text),
   ",\n".join('{t:"%s", go:"%s"}' % (o[0].replace('"','「'), o[1]) for o in opts))

import re
html = open('game.html','r',encoding='utf-8').read()
replaced = 0
for item in R:
    nid, place, opts = item[0], item[1], item[-1]
    text = list(item[2:-1])
    pat = re.compile(r'N\["%s"\]=function\(\)\{return\{.*?\n\}\};' % nid, re.S)
    if pat.search(html):
        html = pat.sub(lambda m: build(nid, place, text, opts), html, count=1)
        replaced += 1
    else:
        print('✗ 未找到: %s' % nid)
header = "\n\n// v41 占位重写·第二批（%d个 旅行路线）\n" % len(R)
pos = html.rfind('</script>')
if pos > 0:
    html = html[:pos] + header + "\n" + html[pos:]
open('game.html','w',encoding='utf-8').write(html)
print('✓ 已替换 %d / %d' % (replaced, len(R)))
